import {destinationOf} from './catalog.js';
export const DESTINATION_FACTS={
 titan:{title:'Titan · seas beneath an amber sky',summary:'Ligeia and Kraken Mare are seas of liquid methane and ethane. Kraken is Titan’s largest known sea, approximately 400,000 km², with complex shorelines and evidence consistent with waves.',detail:'At about −179°C, water is rock-hard ice. A nitrogen-rich atmosphere presses on the surface at about 1.5 times Earth’s surface pressure. That pressure ratio is different from atmospheric density.',medium:'Liquid hydrocarbon sea',sources:[['NASA · Titan facts','https://science.nasa.gov/saturn/moons/titan/facts/'],['NASA · Kraken Mare size','https://science.nasa.gov/resource/titans-northern-polar-clouds/'],['JPL · Cassini sea observations','https://www.jpl.nasa.gov/news/cassini-sails-into-new-ocean-adventures-on-titan/']]},
 moon:{title:'Moon · light and shadow at Shackleton',summary:'Some peaks on Shackleton’s rim receive sunlight for most of the year, while deep parts of its interior stay permanently shadowed. No single rim location has uninterrupted sunlight.',detail:'These extremely cold traps may preserve ancient water ice over very long periods. Artemis studies the south pole for science and possible resources; the amount and accessibility of ice at specific sites remain research questions.',medium:'Solid regolith and impact rock',sources:[['NASA · illuminated rim and shadowed interior','https://science.nasa.gov/resource/shackleton-craters-illuminated-rim-shadowed-interior/'],['NASA · lunar water','https://science.nasa.gov/moon/lunar-water/']]},
 mars:{title:'Mars · Jezero’s ancient river delta',summary:'Jezero is a roughly 45-km-wide impact basin that once held a lake fed by rivers. Sediments built a delta that preserves clues to ancient environments.',detail:'NASA’s Perseverance rover collects rock cores and studies possible signs of ancient microscopic life. No confirmed Martian life has been found; a promising biosignature needs careful investigation.',medium:'Basaltic rock and delta sediments',sources:[['JPL · Jezero landing site','https://www.jpl.nasa.gov/news/press_kits/mars_2020/launch/mission/landing_site/'],['NASA · Perseverance','https://science.nasa.gov/mission/mars-2020-perseverance/']]}
};
export function destinationInfoMarkup(id){
 const d=destinationOf(id),f=DESTINATION_FACTS[d.id];
 return `<button class="dialog-x" data-game="close-info" aria-label="Close destination information">×</button><span class="tiny-label">BEFORE YOU GO · NASA FIELD GUIDE</span><h2 id="destination-info-title">${f.title}</h2><p>${f.summary}</p><p>${f.detail}</p><dl class="physics-badges"><div><dt>Surface gravity</dt><dd>${d.gravity} m/s²</dd></div><div><dt>Air density</dt><dd>${d.density} kg/m³</dd></div><div><dt>Atmosphere</dt><dd>${d.atmosphere}</dd></div><div><dt>Surface</dt><dd>${f.medium}</dd></div></dl><div class="destination-sources">${f.sources.map(([label,url])=>`<a href="${url}" target="_blank" rel="noopener">${label} ↗</a>`).join('')}</div><button class="play-button" data-game="close-info">Back to my mission →</button>`;
}
